mapper.select:
select * from oj_train_plan
where name = #{planName}
and create_user_id = #{userId}

select * from oj_train_plan
where 1=1

    and create_user_id = #{userId}


select * from ( SELECT a.`resource_id`,a.`name`,b.start_time,b.end_time,IFNULL(b.count,0) count,a.update_time,create_user_id, a.`type`, organization_id FROM  `oj_train_plan` a left join

(SELECT min(start_time) start_time,max(end_time) end_time,count(1) count, train_plan_id,max(update_time)  update_time
FROM   oj_classroom
where 1=1

    and (create_user_id = #{userId}

        or (create_user_id = '3f655d87112f4ae094bbaf70830e20aa'

            and course_id in

                #{courseId}


        )

    )

group by train_plan_id) b
on a.resource_id = b.train_plan_id
where 1=1

    and a.create_user_id = #{userId}




    and a.resource_id in (select train_plan_id  FROM   oj_classroom where organization_id = #{organizationId})


union SELECT "${TASK_SET_ID}","${TASK_SET}",min(start_time) start_time,max(end_time) end_time,count(1) count, max(update_time)  update_time ,'-' as create_user_id, 1 as type, organization_id
FROM   oj_classroom where train_plan_id = ''

    and create_user_id = #{userId}


    and organization_id = #{organizationId}

group by train_plan_id
) as aboc where 1=1


and `name` like #{pattern}



        and aboc.`start_time` is not null and aboc.`start_time` > now()


        and aboc.`end_time` is not null and aboc.`end_time` < now()


        and aboc.`start_time` is not null and aboc.start_time < now() and aboc.end_time > now()
